#include "postquantiquecoin/blockchain/Genesis.h"
#include "postquantiquecoin/blockchain/MerkleTree.h"
#include "postquantiquecoin/blockchain/Consensus.h"
#include "postquantiquecoin/core/Hash.h"
#include "postquantiquecoin/crypto/Address.h"
#include "postquantiquecoin/crypto/PQCAddress.h"
#include <chrono>
namespace pqc { Block Genesis::BuildGenesisBlock(const ChainParams& params){ Transaction cb; cb.version=1; cb.timestamp=1704067200ULL; TxInput in; in.previousTxid=Hash::Zero(); in.outputIndex=UINT32_MAX; in.unlockingSignature.assign(CoinbaseText,CoinbaseText+std::char_traits<char>::length(CoinbaseText)); cb.inputs.push_back(in); std::vector<uint8_t> genesisKey{'P','Q','C','_','G','E','N','E','S','I','S','_','P','U','B','K','E','Y'}; cb.publicKey=genesisKey; TxOutput gout; gout.amountAtoms=params.GetBlockSubsidy(0,0); gout.address=Address::FromPublicKey(genesisKey); gout.lockingScriptType="PQC_PUBKEY_HASH"; gout.requiredSignatureAlgorithm=params.defaultSignatureAlgorithm; gout.publicKeyHash=pqc::PQCAddress::HashPublicKey(genesisKey); cb.outputs.push_back(gout); cb.txid=cb.ComputeTxId(); Block b; b.transactions.push_back(cb); b.header.version=1; b.header.consensusVersion=1; b.header.powAlgorithmId=static_cast<uint16_t>(params.powAlgorithm); b.header.previousHash=Hash::Zero(); b.header.timestamp=1704067200ULL; b.header.bits=params.initialBits; b.header.height=0; b.header.merkleRoot=MerkleTree::ComputeRoot(b.transactions); b.header.nonce=0; while(!Consensus::ValidateProofOfWork(b.header, params)) ++b.header.nonce; return b; } bool Genesis::ValidateGenesisBlock(const Block& block,const ChainParams& params){ Block expected=BuildGenesisBlock(params); if(block.GetHash()!=expected.GetHash()) return false; if(!params.expectedGenesisHash.empty() && block.GetHash()!=params.expectedGenesisHash) return false; return block.header.previousHash==Hash::Zero() && block.header.height==0 && block.transactions.size()==1; } }
